import{_ as l,a0 as t,w as o,s as r,ao as d,I as p,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 上查看和配置密码时效 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上查看和配置密码时效 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上查看和配置密码时效 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上查看和配置密码时效 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200317 Viewing and configuring password aging on Linux","title":"在 Linux 上查看和配置密码时效","tag":"202003","desc":""},"relativePath":"202003/20200317 Viewing and configuring password aging on Linux.md","filePath":"[post].md"}'),c={name:"202003/20200317 Viewing and configuring password aging on Linux.md"};function g(u,s,h,b,w,k){const n=t("Link");return o(),r("div",null,[s[18]||(s[18]=d(`<h1 id="在-linux-上查看和配置密码时效" tabindex="-1">在 Linux 上查看和配置密码时效 <a class="header-anchor" href="#在-linux-上查看和配置密码时效" aria-label="Permalink to “在 Linux 上查看和配置密码时效”">​</a></h1><p><img src="https://images.idgesg.net/images/article/2019/09/cso_nw_user_id_password_credentials_authentication_by_bluebay2014_gettyimages-924698706_2400x1600-100811223-large.jpg" alt=""></p><blockquote><p>使用正确的设置，可以强制 Linux 用户定期更改密码。以下是查看密码时效以及如何更改其中设置的方法。</p></blockquote><p>可以将 Linux 系统上的用户密码配置为永久或设置过期时间，以让人们必须定期重置它们。出于安全原因，通常认为定期更改密码是一种好习惯，但默认并未配置。</p><p>要查看和修改密码时效，你需要熟悉几个重要的命令：<code>chage</code> 命令及其 <code>-l</code> 选项，以及 <code>passwd</code> 命令及其 <code>-S</code> 选项。本文会介绍这些命令，还有其他一些 <code>chage</code> 命令选项来配置密码时效。</p><h3 id="查看密码时效设置" tabindex="-1">查看密码时效设置 <a class="header-anchor" href="#查看密码时效设置" aria-label="Permalink to “查看密码时效设置”">​</a></h3><p>确定某个特定帐户是否已设置密码时效的方法是使用如下 <code>chage</code> 命令。请注意，除了你自己的帐户以外，其他任何帐户都需要 root 权限。请注意下面的密码到期日期。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -l dory</span></span>
<span class="line"><span>Last password change                                    : Mar 15, 2020</span></span>
<span class="line"><span>Password expires                                        : Jun 13, 2020    &lt;==</span></span>
<span class="line"><span>Password inactive                                       : never</span></span>
<span class="line"><span>Account expires                                         : never</span></span>
<span class="line"><span>Minimum number of days between password change          : 10</span></span>
<span class="line"><span>Maximum number of days between password change          : 90</span></span>
<span class="line"><span>Number of days of warning before password expires       : 14</span></span></code></pre></div><p>如果未应用密码时效，那么帐户信息将如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -l nemo</span></span>
<span class="line"><span>Last password change                                    : Jan 14, 2019</span></span>
<span class="line"><span>Password expires                                        : never         &lt;==</span></span>
<span class="line"><span>Password inactive                                       : never</span></span>
<span class="line"><span>Account expires                                         : Mar 26, 2706989</span></span>
<span class="line"><span>Minimum number of days between password change          : 0</span></span>
<span class="line"><span>Maximum number of days between password change          : 99999</span></span>
<span class="line"><span>Number of days of warning before password expires       : 7</span></span></code></pre></div><p>你也可以使用 <code>passwd -S</code> 命令查看某些信息，但是你需要知道输出中的每个字段代表什么：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dory$ passwd -S</span></span>
<span class="line"><span>dory P 03/15/2020 10 90 14 -1</span></span></code></pre></div><p>这里的七个字段代表：</p><ul><li>1 – 用户名</li><li>2 - 帐户状态（<code>L</code> = 锁定，<code>NP</code> = 无密码，<code>P</code> = 可用密码）</li><li>3 – 上次密码更改的日期</li><li>4 – 可更改最低时效（如果没有这么多天，则不能更改密码）</li><li>5 – 最长时效（这些天后，密码必须更改）</li><li>6 – 密码过期前提前警告的天数</li><li>7 – 密码过期后锁定之前的天数（设为无效）</li></ul><p>需要注意的一件事是，<code>chage</code> 命令不会显示帐户是否被锁定；它仅显示密码时效设置。另一方面，<code>passwd -S</code> 命令将告诉你密码被锁定的时间。在此例中，请注意帐户状态为 <code>L</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo passwd -S dorothy</span></span>
<span class="line"><span>dorothy L 07/09/2019 0 99999 7 10</span></span></code></pre></div><p>通过将 <code>/etc/shadow</code> 文件中通常包含密码的“哈希”字段变为 <code>!</code>，从而达成锁定的效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo grep dorothy /etc/shadow</span></span>
<span class="line"><span>dorothy:!:18086:0:99999:7:10::    &lt;==</span></span></code></pre></div><p>帐户被锁定的事实在 <code>chage</code> 输出中并不明显：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -l dorothy</span></span>
<span class="line"><span>Last password change                                    : Jul 09, 2019</span></span>
<span class="line"><span>Password expires                                        : never</span></span>
<span class="line"><span>Password inactive                                       : never</span></span>
<span class="line"><span>Account expires                                         : never</span></span>
<span class="line"><span>Minimum number of days between password change          : 0</span></span>
<span class="line"><span>Maximum number of days between password change          : 99999</span></span>
<span class="line"><span>Number of days of warning before password expires       : 7</span></span></code></pre></div><h3 id="密码时效的一些选项" tabindex="-1">密码时效的一些选项 <a class="header-anchor" href="#密码时效的一些选项" aria-label="Permalink to “密码时效的一些选项”">​</a></h3><p>最常用的设置是最短和最长的天数。它们经常结合使用。例如，你可以配置一个密码，使其最长不能使用超过 90 天（最大），然后添加一个有效期为一周或 10 天（最小）的密码。这样可以确保用户不会在需要更改密码后马上改回以前的密码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -M 90 -m 10 shark</span></span>
<span class="line"><span>$ sudo chage -l shark</span></span>
<span class="line"><span>Last password change                                    : Mar 16, 2020</span></span>
<span class="line"><span>Password expires                                        : Jun 14, 2020</span></span>
<span class="line"><span>Password inactive                                       : never</span></span>
<span class="line"><span>Account expires                                         : never</span></span>
<span class="line"><span>Minimum number of days between password change          : 10    &lt;==</span></span>
<span class="line"><span>Maximum number of days between password change          : 90    &lt;==</span></span>
<span class="line"><span>Number of days of warning before password expires       : 7</span></span></code></pre></div><p>你还可以使用 <code>-E</code> 选项为帐户设置特定的到期日期。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -E 2020-11-11 tadpole</span></span>
<span class="line"><span>$ sudo chage -l tadpole</span></span>
<span class="line"><span>Last password change                                    : Oct 15, 2019</span></span>
<span class="line"><span>Password expires                                        : never</span></span>
<span class="line"><span>Password inactive                                       : never</span></span>
<span class="line"><span>Account expires                                         : Nov 11, 2020  &lt;==</span></span>
<span class="line"><span>Minimum number of days between password change          : 0</span></span>
<span class="line"><span>Maximum number of days between password change          : 99999</span></span>
<span class="line"><span>Number of days of warning before password expires       : 7</span></span></code></pre></div>`,25)),p("p",null,[s[1]||(s[1]=a("密码时效可能是一个重要的选择，只要它不鼓励用户使用过于简单的密码或以不安全的方式写下来即可。有关控制密码字符（例如，大小写字母、数字等的组合）的更多信息，请参考这篇关于",-1)),e(n,{href:"https://www.networkworld.com/article/2726217/how-to-enforce-password-complexity-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[a("密码复杂度",-1)])]),_:1}),s[2]||(s[2]=a("的文章。",-1))]),s[19]||(s[19]=p("hr",null,null,-1)),p("p",null,[s[4]||(s[4]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3532815/viewing-and-configuring-password-aging-on-linux.html"},{default:i(()=>[...s[3]||(s[3]=[a("https://www.networkworld.com/article/3532815/viewing-and-configuring-password-aging-on-linux.html",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[5]||(s[5]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[a("geekpi",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const y=l(c,[["render",g]]);export{x as __pageData,y as default};
